import React, { useState } from 'react';
import './App.css';
import { BrowserRouter as Router, Routes, Route, useNavigate, useParams } from 'react-router-dom';

function OntologyDetail({ ontologies }) {
  const { id } = useParams();
  const ontology = ontologies && ontologies[parseInt(id, 10)];
  if (!ontology) return <div className="ontology-detail-bg"><div className="ontology-detail-card"><h2>Ontology not found</h2></div></div>;
  // Placeholder reused ontologies
  const reusedOntologies = [
    { name: 'FOAF', url: 'https://www.foaf-project.org/' },
    { name: 'Dublin Core', url: 'https://dublincore.org/' },
    { name: 'SKOS', url: 'https://www.w3.org/2004/02/skos/core#' }
  ];
  return (
    <div className="ontology-detail-layout">
      <div className="ontology-detail-main">
        <div className="ontology-detail-header">
          <h2>{ontology.title}</h2>
        </div>
        <div className="ontology-detail-publisher">
          <span className="ontology-detail-publisher-label">Publisher:</span> {ontology.publisherName || ontology.publisher}
        </div>
        <div className="ontology-detail-description">
          {ontology.description}
        </div>
        <div className="ontology-detail-section">
          <h3>Distributions</h3>
          <table className="ontology-detail-table">
            <thead>
              <tr>
                <th>Link to the data</th>
                <th>Format</th>
                <th>Updated</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>ontology</td>
                <td>HTML</td>
                <td>UNKNOWN</td>
                <td>Access</td>
              </tr>
            </tbody>
          </table>
        </div>
        <div className="ontology-detail-section">
          <h3>Keywords</h3>
          <ul className="ontology-detail-keywords">
            <li>ontology</li>
            <li>example</li>
            <li>data</li>
          </ul>
        </div>
        <div className="ontology-detail-section">
          <h3>Main Classes</h3>
          {ontology.mainClasses && ontology.mainClasses.length > 0 ? (
            <ul className="ontology-detail-keywords">
              {ontology.mainClasses.map((cls, idx) => (
                <li key={idx}>{cls}</li>
              ))}
            </ul>
          ) : (
            <span style={{ color: '#7eb6ff' }}>No main classes listed.</span>
          )}
        </div>
      </div>
      <aside className="ontology-detail-meta">
        <div className="ontology-detail-meta-box">
          <div><b>Ranking:</b> {ontology.ranking}</div>
          <div><b>Created:</b> 31.01.2025</div>
          <div><b>Landing Page:</b> <a href="#" target="_blank" rel="noopener noreferrer">example.com</a></div>
          <div><b>Languages:</b> Dutch</div>
        </div>
        <div className="ontology-detail-reuses-box">
          <div className="ontology-detail-reuses-title">This ontology reuses:</div>
          <ul className="ontology-detail-reuses-list">
            {reusedOntologies.map((onto, idx) => (
              <li key={idx}><a href={onto.url} target="_blank" rel="noopener noreferrer">{onto.name}</a></li>
            ))}
          </ul>
        </div>
      </aside>
    </div>
  );
}

function SearchPage({ search, setSearch, submittedQuery, setSubmittedQuery, results, setResults, loading, setLoading, error, setError }) {
  const navigate = useNavigate();
  const handleKeyDown = async (e) => {
    if (e.key === 'Enter') {
      setSubmittedQuery(search);
      setLoading(true);
      setError(null);
      setResults([]);
      try {
        const response = await fetch('http://localhost:4000/api/search', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: search })
        });
        if (!response.ok) {
          throw new Error('Failed to fetch results');
        }
        const data = await response.json();
        setResults(data);
      } catch (err) {
        setError(err.message || 'Unknown error');
      } finally {
        setLoading(false);
      }
    }
  };
  return (
    <div className="main-content">
      <div className="search-bar">
        <input
          type="text"
          placeholder="Search ontologies..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          onKeyDown={handleKeyDown}
        />
      </div>
      {loading && <p className="loading">Loading...</p>}
      {error && <p className="error">{error}</p>}
      {submittedQuery && !loading && !error && (
        <div className="results">
          {results.length === 0 ? (
            <p className="no-results">No ontologies found.</p>
          ) : (
            results.map((onto, idx) => (
              <div
                className="ontology-card"
                key={idx}
                style={{ cursor: 'pointer' }}
                onClick={() => navigate(`/ontology/${idx}`)}
              >
                <h2>{onto.title}</h2>
                <p className="description">{onto.description}</p>
                <div className="meta">
                  <span className="publisher">Publisher: {onto.publisherName || onto.publisher}</span>
                  <span className="ranking">Ranking: {onto.ranking}</span>
                </div>
                {onto.mainClasses && onto.mainClasses.length > 0 && (
                  <div className="main-classes-list">
                    <span className="main-classes-label">Main classes:</span> {onto.mainClasses.join(', ')}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

function App() {
  const [search, setSearch] = useState('');
  const [submittedQuery, setSubmittedQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const navigate = useNavigate();

  const handleTitleClick = () => {
    setSearch('');
    setSubmittedQuery('');
    setResults([]);
    setError(null);
    setLoading(false);
    navigate('/');
  };

  return (
    <>
      <nav className="navbar">
        <div className="navbar-content">
          <h1 onClick={handleTitleClick}>The Semantic Registry</h1>
          <p>Search for semantic ontologies</p>
        </div>
      </nav>
      <Routes>
        <Route path="/" element={
          <SearchPage
            search={search}
            setSearch={setSearch}
            submittedQuery={submittedQuery}
            setSubmittedQuery={setSubmittedQuery}
            results={results}
            setResults={setResults}
            loading={loading}
            setLoading={setLoading}
            error={error}
            setError={setError}
          />
        } />
        <Route path="/ontology/:id" element={<OntologyDetail ontologies={results} />} />
      </Routes>
    </>
  );
}

export default function AppWithRouter() {
  return (
    <Router>
      <App />
    </Router>
  );
}
